using System;
using System.Globalization;
using System.IO;
using System.Text;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade
{
    public class CutListComponent : FacadeComponent
    {
        public CutListComponent()
            : base("Cut List", "CutList", "CSV cut list of panels", "Fabrication") { }

        public override Guid ComponentGuid => new Guid("c0a1b2d3-9999-4a00-9b01-5f0e00000009");

        protected override void RegisterInputParams(GH_InputParamManager m)
        {
            AddPanels(m);
            m.AddTextParameter("Path", "P", "CSV file path", GH_ParamAccess.item, "");
            m.AddBooleanParameter("Write", "W", "Write the file", GH_ParamAccess.item, false);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager m)
        {
            m.AddTextParameter("CSV", "CSV", "Cut list text", GH_ParamAccess.item);
            m.AddBooleanParameter("Written", "W", "True when the file was written", GH_ParamAccess.item);
        }

        private static string F(double d) => d.ToString("0.###", CultureInfo.InvariantCulture);

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = GetPanels(DA);
            string path = "";
            bool write = false;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);
            if (panels == null) return;

            var sb = new StringBuilder("Index,Width,Height,Area,Deviation\n");
            foreach (var p in panels)
                sb.Append(p.Index.ToString(CultureInfo.InvariantCulture)).Append(',')
                  .Append(F(p.Width)).Append(',').Append(F(p.Height)).Append(',')
                  .Append(F(p.Area)).Append(',').Append(F(p.Deviation)).Append('\n');
            string csv = sb.ToString();

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty.");
                else
                {
                    try { File.WriteAllText(path, csv); written = true; }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Could not write file: " + ex.Message);
                    }
                }
            }
            DA.SetData(0, csv);
            DA.SetData(1, written);
        }
    }
}
