using System;
using System.Linq;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>One four-sided facade panel cut from a surface.</summary>
    public class Panel
    {
        public Panel(Point3d[] corners, int index)
        {
            if (corners == null || corners.Length != 4) throw new ArgumentException("A panel needs four corners.");
            Corners = (Point3d[])corners.Clone();
            Index = index;
        }

        /// <summary>Corners in order around the panel.</summary>
        public Point3d[] Corners { get; }
        public int Index { get; }

        public Curve Outline =>
            new PolylineCurve(new[] { Corners[0], Corners[1], Corners[2], Corners[3], Corners[0] });

        public Point3d Center =>
            new Point3d(Corners.Average(c => c.X), Corners.Average(c => c.Y), Corners.Average(c => c.Z));

        public double Area
        {
            get
            {
                Vector3d n = Vector3d.CrossProduct(Corners[2] - Corners[0], Corners[3] - Corners[1]);
                return 0.5 * n.Length;
            }
        }

        /// <summary>Distance from the fourth corner to the plane through the first three.</summary>
        public double Deviation
        {
            get
            {
                Vector3d n = Vector3d.CrossProduct(Corners[1] - Corners[0], Corners[2] - Corners[0]);
                if (!n.Unitize()) return 0.0;
                return Math.Abs(n * (Corners[3] - Corners[0]));
            }
        }

        public double[] EdgeLengths => new[]
        {
            Corners[0].DistanceTo(Corners[1]),
            Corners[1].DistanceTo(Corners[2]),
            Corners[2].DistanceTo(Corners[3]),
            Corners[3].DistanceTo(Corners[0]),
        };

        public double[] DiagonalLengths => new[]
        {
            Corners[0].DistanceTo(Corners[2]),
            Corners[1].DistanceTo(Corners[3]),
        };

        /// <summary>Mean of the first and third edge lengths.</summary>
        public double Width { get { var e = EdgeLengths; return (e[0] + e[2]) / 2.0; } }

        /// <summary>Mean of the second and fourth edge lengths.</summary>
        public double Height { get { var e = EdgeLengths; return (e[1] + e[3]) / 2.0; } }
    }
}
