    {
        public PlanarityComponent()
            : base("Planarity", "Planarity", "Planarity deviation of panels", "Analysis") { }

        public override Guid ComponentGuid => new Guid("c0a1b2d3-4444-4a00-9b01-5f0e00000004");

        protected override void RegisterInputParams(GH_InputParamManager m)
