            AddPanels(m);
            m.AddNumberParameter("Tolerance", "T", "Maximum deviation for a flat panel", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager m)
        {
            m.AddNumberParameter("Deviation", "D", "Deviation per panel", GH_ParamAccess.list);
            m.AddBooleanParameter("Flat", "F", "True when deviation is within tolerance", GH_ParamAccess.list);
            m.AddIntegerParameter("Flat Count", "N", "Number of flat panels", GH_ParamAccess.item);
