using System;
using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade
{
    public class GroupIdenticalPanelsComponent : FacadeComponent
    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group", "Group panels with the same dimensions", "Fabrication") { }

        public override Guid ComponentGuid => new Guid("c0a1b2d3-7777-4a00-9b01-5f0e00000007");

        protected override void RegisterInputParams(GH_InputParamManager m)
        {
            AddPanels(m);
            m.AddNumberParameter("Tolerance", "T", "Length tolerance", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager m)
        {
            m.AddIntegerParameter("Group", "G", "Group number per panel", GH_ParamAccess.list);
            m.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            m.AddParameter(new PanelParam(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        private static double[] Signature(Panel p)
        {
            return p.EdgeLengths.OrderBy(x => x).Concat(p.DiagonalLengths.OrderBy(x => x)).ToArray();
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = GetPanels(DA);
            double tol = 1.0;
            DA.GetData(1, ref tol);
            if (panels == null) return;

            var reps = new List<Panel>();
            var repSigs = new List<double[]>();
            var groups = new List<int>();
            foreach (var p in panels)
            {
                var sig = Signature(p);
                int g = -1;
                for (int k = 0; k < repSigs.Count && g < 0; k++)
                {
                    var r = repSigs[k];
                    bool same = true;
                    for (int i = 0; i < 4 && same; i++) same = Math.Abs(sig[i] - r[i]) <= tol;
                    for (int i = 4; i < 6 && same; i++) same = Math.Abs(sig[i] - r[i]) <= tol;
                    if (same) g = k;
                }
                if (g < 0)
                {
                    g = reps.Count;
                    reps.Add(p);
                    repSigs.Add(sig);
                }
                groups.Add(g);
            }
            DA.SetDataList(0, groups);
            DA.SetData(1, reps.Count);
            DA.SetDataList(2, reps.Select(r => new PanelGoo(r)).ToList());
        }
    }
}
