namespace BenchPlugin.Facade
{
    public abstract class FacadeComponent : GH_Component
    {
        protected FacadeComponent(string name, string nick, string desc, string sub)
            : base(name, nick, desc, "Facade", sub) { }

        protected static void AddPanels(GH_InputParamManager m, GH_ParamAccess access = GH_ParamAccess.list)
        {
            m.AddParameter(new PanelParam(), "Panels", "P", "Facade panels", access);
        }

        /// <summary>Reads the panel list at the given index; returns null when nothing usable was supplied.</summary>
        protected static List<Panel> GetPanels(IGH_DataAccess DA, int index = 0)
        {
            var goos = new List<PanelGoo>();
            if (!DA.GetDataList(index, goos)) return null;
            return goos.Where(g => g != null && g.Value != null).Select(g => g.Value).ToList();
        }
    }
}

