    public class ClassifyPanelsComponent : FacadeComponent
    {
        public ClassifyPanelsComponent()
            : base("Classify Panels", "Classify", "Classify panels as flat, cold-bent or custom", "Analysis") { }

        public override Guid ComponentGuid => new Guid("c0a1b2d3-5555-4a00-9b01-5f0e00000005");

        protected override void RegisterInputParams(GH_InputParamManager m)
        {
            AddPanels(m);
            m.AddNumberParameter("Tolerance", "T", "Flatness tolerance", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager m)
        {
            m.AddTextParameter("Type", "T", "flat, cold-bent or custom per panel", GH_ParamAccess.list);
            m.AddIntegerParameter("Flat Count", "F", "Flat panels", GH_ParamAccess.item);
            m.AddIntegerParameter("Cold Bent Count", "C", "Cold-bent panels", GH_ParamAccess.item);
            m.AddIntegerParameter("Custom Count", "X", "Custom panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = GetPanels(DA);
            double tol = 0.5;
            DA.GetData(1, ref tol);
            if (panels == null) return;

            var types = panels.Select(p =>
            {
                double d = p.Deviation;
                return d <= tol ? "flat" : d <= 10 * tol ? "cold-bent" : "custom";
            }).ToList();
            DA.SetDataList(0, types);
            DA.SetData(1, types.Count(t => t == "flat"));
            DA.SetData(2, types.Count(t => t == "cold-bent"));
            DA.SetData(3, types.Count(t => t == "custom"));
        }
    }
}

