using System;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class PanelizeSurfaceComponent : FacadeComponent
    {
        public PanelizeSurfaceComponent()
            : base("Panelize Surface", "Panelize", "Divide a surface into four-sided panels", "Panels") { }

        public override Guid ComponentGuid => new Guid("c0a1b2d3-2222-4a00-9b01-5f0e00000002");

        protected override void RegisterInputParams(GH_InputParamManager m)
        {
            m.AddSurfaceParameter("Surface", "S", "Surface to panelize", GH_ParamAccess.item);
            m.AddIntegerParameter("U Count", "U", "Panels in U direction", GH_ParamAccess.item, 10);
            m.AddIntegerParameter("V Count", "V", "Panels in V direction", GH_ParamAccess.item, 6);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager m)
        {
            m.AddParameter(new PanelParam(), "Panels", "P", "Panels", GH_ParamAccess.list);
            m.AddCurveParameter("Outlines", "O", "Closed panel outlines", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            Surface srf = null;
            int uc = 10, vc = 6;
            if (!DA.GetData(0, ref srf) || srf == null) return;
            DA.GetData(1, ref uc);
            DA.GetData(2, ref vc);
            if (uc < 1 || vc < 1)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "U Count and V Count must be at least 1.");
                return;
            }

            Interval du = srf.Domain(0), dv = srf.Domain(1);
            var pts = new Point3d[uc + 1, vc + 1];
            for (int i = 0; i <= uc; i++)
                for (int j = 0; j <= vc; j++)
                    pts[i, j] = srf.PointAt(du.ParameterAt((double)i / uc), dv.ParameterAt((double)j / vc));

            var panels = new List<PanelGoo>();
            var outlines = new List<Curve>();
            int index = 0;
            for (int i = 0; i < uc; i++)
                for (int j = 0; j < vc; j++)
                {
                    var p = new Panel(new[] { pts[i, j], pts[i + 1, j], pts[i + 1, j + 1], pts[i, j + 1] }, index++);
                    panels.Add(new PanelGoo(p));
                    outlines.Add(p.Outline);
                }
            DA.SetDataList(0, panels);
            DA.SetDataList(1, outlines);
        }
    }
}
