        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = GetPanels(DA);
            string path = "";
            bool write = false;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);
            if (panels == null) return;

            var sb = new StringBuilder("Index,Width,Height,Area,Deviation\n");
            foreach (var p in panels)
                sb.Append(p.Index.ToString(CultureInfo.InvariantCulture)).Append(',')
                  .Append(F(p.Width)).Append(',').Append(F(p.Height)).Append(',')
                  .Append(F(p.Area)).Append(',').Append(F(p.Deviation)).Append('\n');
            string csv = sb.ToString();

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty.");
                else
                {
                    try { File.WriteAllText(path, csv); written = true; }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Could not write file: " + ex.Message);
                    }
                }
            }
            DA.SetData(0, csv);
            DA.SetData(1, written);
        }
    }
}
