cat > NestOnSheets.cs <<'EOF'
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class NestOnSheetsComponent : FacadeComponent
    {
        private class Placed { public double X, Y, W, H; public int Sheet; }

        private class NestResult
        {
            public List<Placed> Parts = new List<Placed>();
            public int SheetCount;
            public int Unplaced;
            public double Utilization;
        }

        private readonly object _lock = new object();
        private CancellationTokenSource _cts;
        private Task _task;
        private NestResult _result;
        private int _resultKey, _runKey;
        private int _progress;

        public NestOnSheetsComponent()
            : base("Nest On Sheets", "Nest", "Shelf-nest panel rectangles on sheets", "Fabrication") { }

        public override Guid ComponentGuid => new Guid("c0a1b2d3-8888-4a00-9b01-5f0e00000008");

        protected override void RegisterInputParams(GH_InputParamManager m)
        {
            AddPanels(m);
            m.AddNumberParameter("Sheet Width", "W", "Sheet width", GH_ParamAccess.item, 3000.0);
            m.AddNumberParameter("Sheet Height", "H", "Sheet height", GH_ParamAccess.item, 1500.0);
            m.AddNumberParameter("Spacing", "S", "Gap between parts and from sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager m)
        {
            m.AddCurveParameter("Outlines", "O", "Placed rectangles", GH_ParamAccess.list);
            m.AddIntegerParameter("Sheet", "S", "Sheet index per placed panel", GH_ParamAccess.list);
            m.AddIntegerParameter("Sheet Count", "N", "Number of sheets used", GH_ParamAccess.item);
            m.AddNumberParameter("Utilization", "U", "Placed area / total sheet area", GH_ParamAccess.item);
        }

        private void CancelRun()
        {
            lock (_lock)
            {
                _cts?.Cancel();
                _cts = null;
            }
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            CancelRun();
            base.RemovedFromDocument(document);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = GetPanels(DA);
            double w = 3000, h = 1500, sp = 10;
            DA.GetData(1, ref w);
            DA.GetData(2, ref h);
            DA.GetData(3, ref sp);
            if (panels == null) return;
            if (w <= 0 || h <= 0 || sp < 0)
            {
                CancelRun();
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Sheet size must be positive and Spacing not negative.");
                return;
            }

            var parts = panels.Select(p => new[] { p.Width, p.Height }).ToList();
            var hc = new HashCode();
            hc.Add(w); hc.Add(h); hc.Add(sp);
            foreach (var p in parts) { hc.Add(p[0]); hc.Add(p[1]); }
            int key = hc.ToHashCode();

            NestResult done = null;
            bool running = false;
            lock (_lock)
            {
                if (_result != null && _resultKey == key) done = _result;
                else if (_task != null && !_task.IsCompleted && _runKey == key && _cts != null) running = true;
            }

            if (done != null)
            {
                Message = "";
                Output(DA, done, w, h);
                return;
            }
            if (running)
            {
                Message = $"Nesting {_progress}%";
                return;
            }

            CancelRun();
            var cts = new CancellationTokenSource();
            var token = cts.Token;
            var doc = OnPingDocument();
            lock (_lock)
            {
                _cts = cts;
                _runKey = key;
                _result = null;
                _progress = 0;
            }
            Message = "Nesting 0%";

            Task t = Task.Run(() =>
            {
                var r = Nest(parts, w, h, sp, token, pct =>
                {
                    if (pct == _progress) return;
                    _progress = pct;
                    var canvas = Instances.ActiveCanvas;
                    if (canvas != null && !token.IsCancellationRequested)
                        canvas.BeginInvoke(new Action(() =>
                        {
                            if (token.IsCancellationRequested) return;
                            Message = $"Nesting {pct}%";
                            canvas.Invalidate();
                        }));
                });
                if (token.IsCancellationRequested || r == null) return;
                lock (_lock)
                {
                    if (token.IsCancellationRequested) return;
                    _resultKey = key;
                    _result = r;
                }
                doc?.ScheduleSolution(1, d => ExpireSolution(false));
            });
            lock (_lock) { _task = t; }
        }

        private static void Output(IGH_DataAccess DA, NestResult r, double w, double h)
        {
            var outlines = new List<Curve>();
            var sheets = new List<int>();
            foreach (var p in r.Parts)
            {
                double ox = p.Sheet * (w + 100.0) + p.X;
                var rect = new Rectangle3d(Plane.WorldXY, new Point3d(ox, p.Y, 0), new Point3d(ox + p.W, p.Y + p.H, 0));
                outlines.Add(rect.ToNurbsCurve());
                sheets.Add(p.Sheet);
            }
            DA.SetDataList(0, outlines);
            DA.SetDataList(1, sheets);
            DA.SetData(2, r.SheetCount);
            DA.SetData(3, r.Utilization);
        }

        protected override void AfterSolveInstance()
        {
            base.AfterSolveInstance();
            NestResult r;
            lock (_lock) { r = _result; }
            if (r != null && r.Unplaced > 0)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning, $"{r.Unplaced} panel(s) fit on no sheet.");
        }

        private static NestResult Nest(List<double[]> parts, double W, double H, double sp,
            CancellationToken token, Action<int> progress)
        {
            var res = new NestResult();
            var order = parts.OrderByDescending(p => p[1]).ToList();

            int sheet = -1;
            double shelfY = 0, shelfH = 0, cursorX = 0;
            bool haveShelf = false;
            double area = 0;

            bool Fits(double pw, double ph) => pw + 2 * sp <= W && ph + 2 * sp <= H;

            for (int n = 0; n < order.Count; n++)
            {
                if (token.IsCancellationRequested) return null;
                progress(order.Count == 0 ? 100 : n * 100 / order.Count);

                double pw = order[n][0], ph = order[n][1];
                bool turn = false;
                bool placed = false;
                double x = 0, y = 0;

                if (!Fits(pw, ph) && !Fits(ph, pw)) { res.Unplaced++; continue; }

                // Current shelf
                if (haveShelf)
                {
                    if (cursorX + pw + sp <= W && ph <= shelfH) { x = cursorX; y = shelfY; placed = true; }
                    else if (cursorX + ph + sp <= W && pw <= shelfH) { x = cursorX; y = shelfY; turn = true; placed = true; }
                }

                if (!placed)
                {
                    // New shelf on current sheet
                    if (haveShelf)
                    {
                        double ny = shelfY + shelfH + sp;
                        if (pw + 2 * sp <= W && ny + ph + sp <= H) { shelfY = ny; shelfH = ph; cursorX = sp; x = sp; y = ny; placed = true; }
                        else if (ph + 2 * sp <= W && ny + pw + sp <= H) { shelfY = ny; shelfH = pw; cursorX = sp; x = sp; y = ny; turn = true; placed = true; }
                    }
                }

                if (!placed)
                {
                    // New sheet
                    sheet++;
                    haveShelf = true;
                    shelfY = sp; cursorX = sp;
                    if (Fits(pw, ph)) { shelfH = ph; }
                    else { shelfH = pw; turn = true; }
                    x = sp; y = sp;
                }

                double rw = turn ? ph : pw, rh = turn ? pw : ph;
                res.Parts.Add(new Placed { X = x, Y = y, W = rw, H = rh, Sheet = sheet });
                cursorX = x + rw + sp;
                area += rw * rh;
            }

            res.SheetCount = sheet + 1;
            res.Utilization = res.SheetCount > 0 ? area / (res.SheetCount * W * H) : 0.0;
            progress(100);
            return res;
        }
    }
}
